) ENGINE=InnoDB AUTO_INCREMENT=257 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='레이아웃 컬럼 및 섹션 매핑';


DROP TABLE IF EXISTS `layout_presets`;
CREATE TABLE `layout_presets` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `preset_name` varchar(100) NOT NULL COMMENT '프리셋 이름',
