  KEY `created_by` (`created_by`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='레이아웃 프리셋 템플릿';


DROP TABLE IF EXISTS `layout_rows`;
