  `old_margin_rate` decimal(5,2) DEFAULT NULL,
  `new_margin_rate` decimal(5,2) DEFAULT NULL,
  `change_type` enum('cost_only','selling_only','both','margin_adjust') NOT NULL DEFAULT 'both',
  `change_reason` varchar(255) DEFAULT NULL,
  `purchase_id` varchar(50) DEFAULT NULL COMMENT '매입이력에서 변경된 경우 매입ID',
  `changed_by_user_id` int(11) NOT NULL,
  `changed_at` timestamp NULL DEFAULT current_timestamp(),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_changed_at` (`changed_at`),
  KEY `idx_changed_by_user_id` (`changed_by_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='상품 가격변경 이력';


DROP TABLE IF EXISTS `price_label_project_items`;
CREATE TABLE `price_label_project_items` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL COMMENT '프로젝트 ID (FK)',
  `product_id` int(11) unsigned NOT NULL COMMENT '상품 ID (FK)',
  `quantity` int(11) NOT NULL DEFAULT 1 COMMENT '출력 매수',
  `remarks` varchar(255) DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '추가일',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_project_product` (`project_id`,`product_id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_product_id` (`product_id`),
  CONSTRAINT `price_label_project_items_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `price_label_projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `price_label_project_items_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='가격표\r\n  프로젝트별 상품 아이템 테이블';


DROP TABLE IF EXISTS `price_label_projects`;
CREATE TABLE `price_label_projects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_name` varchar(255) NOT NULL COMMENT '프로젝트명',
  `description` text DEFAULT NULL COMMENT '프로젝트 설명',
  `store_id` int(11) NOT NULL COMMENT '점포 ID',
  `created_by` int(11) NOT NULL COMMENT '생성자 사용자 ID',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '생성일',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일',
  PRIMARY KEY (`id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='가격표 출력 프로젝트 메인 테이블';


DROP TABLE IF EXISTS `product_displays`;
CREATE TABLE `product_displays` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `section_id` int(11) NOT NULL COMMENT '진열 섹션 ID',
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `store_id` int(11) NOT NULL COMMENT '점포 ID',
  `display_order` int(11) NOT NULL DEFAULT 0 COMMENT '섹션 내 표시 순서',
  `custom_title` varchar(255) DEFAULT NULL COMMENT '커스텀 제목',
  `custom_description` text DEFAULT NULL COMMENT '커스텀 설명',
  `custom_image_url` varchar(500) DEFAULT NULL COMMENT '커스텀 이미지 URL',
  `badge_text` varchar(50) DEFAULT NULL COMMENT '배지 텍스트 (예: NEW, SALE)',
  `badge_color` enum('red','blue','green','orange','purple','gray') DEFAULT NULL COMMENT '배지 색상',
  `start_date` date DEFAULT NULL COMMENT '진열 시작일',
  `end_date` date DEFAULT NULL COMMENT '진열 종료일',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `click_count` int(11) DEFAULT 0 COMMENT '클릭 수 (통계용)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_section_product_store` (`section_id`,`product_id`,`store_id`),
  KEY `section_id` (`section_id`),
  KEY `product_id` (`product_id`),
  KEY `store_id` (`store_id`),
  KEY `idx_product_displays_order` (`section_id`,`display_order`),
  KEY `idx_product_displays_active` (`is_active`),
  KEY `idx_product_displays_date` (`start_date`,`end_date`),
  CONSTRAINT `product_displays_ibfk_1` FOREIGN KEY (`section_id`) REFERENCES `display_sections` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='상품 진열 관리';


DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `sku` varchar(100) NOT NULL,
  `name_ko` varchar(255) NOT NULL,
  `name_en` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `category_id` int(11) unsigned DEFAULT NULL,
  `is_vat_applicable` tinyint(1) DEFAULT 1 COMMENT 'VAT 적용 여부 (1=적용, 0=비적용)',
  `brand_id` int(11) unsigned DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `last_modified_by_user_id` int(11) unsigned DEFAULT NULL,
  `pieces_per_box` int(11) DEFAULT 1,
  `status` enum('active','inactive','discontinued') DEFAULT 'active',
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `brand_id` (`brand_id`),
  KEY `last_modified_by_user_id` (`last_modified_by_user_id`),
  KEY `idx_products_vat_applicable` (`is_vat_applicable`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_ibfk_3` FOREIGN KEY (`last_modified_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=23669 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `purchase_items`;
CREATE TABLE `purchase_items` (
  `item_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `purchase_id` int(10) unsigned NOT NULL,
  `product_id` int(11) unsigned NOT NULL,
  `purchase_type` enum('box','piece') NOT NULL DEFAULT 'box',
  `quantity` int(11) NOT NULL,
  `unit_price` decimal(10,2) NOT NULL,
  `vat_included` tinyint(1) DEFAULT 1 COMMENT 'VAT 포함 여부 (1=포함, 0=미포함)',
  `original_unit_price` decimal(10,2) DEFAULT NULL COMMENT '입력된 원본 단가',
  `vat_amount` decimal(10,2) DEFAULT 0.00 COMMENT 'VAT 금액',
  `discount_rate` decimal(5,2) DEFAULT 0.00 COMMENT '할인율 (%)',
  `discounted_total` decimal(10,2) DEFAULT NULL COMMENT '할인후 총액',
  PRIMARY KEY (`item_id`),
  KEY `purchase_id` (`purchase_id`),
  KEY `product_id` (`product_id`),
  KEY `idx_purchase_items_vat_included` (`vat_included`),
  CONSTRAINT `purchase_items_ibfk_1` FOREIGN KEY (`purchase_id`) REFERENCES `purchases` (`purchase_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `purchase_items_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=546 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `purchases`;
CREATE TABLE `purchases` (
  `purchase_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `store_id` int(11) unsigned NOT NULL DEFAULT 1 COMMENT '점포 ID',
  `supplier_id` int(11) unsigned NOT NULL,
  `purchase_date` date NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `total_items` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by_user_id` int(11) DEFAULT NULL,
  `is_confirmed` tinyint(1) DEFAULT 0 COMMENT '매입 확정 여부 (0: 미확정, 1: 확정)',
  `confirmed_at` datetime DEFAULT NULL COMMENT '확정 일시',
  `confirmed_by_user_id` int(11) DEFAULT NULL COMMENT '확정한 사용자 ID',
  PRIMARY KEY (`purchase_id`),
  KEY `supplier_id` (`supplier_id`),
  KEY `idx_is_confirmed` (`is_confirmed`),
  KEY `idx_confirmed_at` (`confirmed_at`),
  KEY `idx_purchases_store_id` (`store_id`),
  CONSTRAINT `fk_purchases_store_id` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `purchases_ibfk_1` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(255) NOT NULL,
  `setting_value` text NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `setting_key` (`setting_key`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `shipping_addresses`;
CREATE TABLE `shipping_addresses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `order_id` int(11) DEFAULT NULL,
  `recipient_name` varchar(100) NOT NULL,
  `recipient_phone` varchar(20) NOT NULL,
  `address_line1` varchar(255) NOT NULL,
  `address_line2` varchar(255) DEFAULT NULL,
  `city` varchar(100) NOT NULL,
  `postal_code` varchar(20) DEFAULT NULL,
  `is_default` tinyint(1) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `shop_menu_products`;
CREATE TABLE `shop_menu_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `menu_id` int(11) NOT NULL COMMENT '메뉴 ID (shop_menus 테이블과 연결)',
  `product_id` int(11) NOT NULL COMMENT '상품 ID (products 테이블과 연결)',
  `display_order` int(11) DEFAULT 0 COMMENT '메뉴 내 상품 표시 순서',
  `is_featured` tinyint(1) DEFAULT 0 COMMENT '해당 메뉴의 추천 상품 여부',
  `added_by` int(11) DEFAULT NULL COMMENT '상품을 메뉴에 추가한 사용자 ID',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_menu_product` (`menu_id`,`product_id`),
  KEY `idx_menu_products_menu` (`menu_id`),
  KEY `idx_menu_products_product` (`product_id`),
  KEY `idx_menu_products_order` (`menu_id`,`display_order`),
  KEY `idx_menu_products_featured` (`menu_id`,`is_featured`),
  KEY `idx_menu_products_added_by` (`added_by`),
  KEY `idx_menu_products_menu_order` (`menu_id`,`display_order`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='메뉴별 상품 연결 관리';


DROP TABLE IF EXISTS `shop_menus`;
CREATE TABLE `shop_menus` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '메뉴명 (예: 홈, 전단지상품, 특가상품)',
  `name_en` varchar(100) DEFAULT NULL COMMENT '영문 메뉴명',
  `description` text DEFAULT NULL COMMENT '메뉴 설명',
  `display_order` int(11) NOT NULL DEFAULT 0 COMMENT '메뉴 표시 순서',
  `icon_class` varchar(50) DEFAULT NULL COMMENT 'FontAwesome 아이콘 클래스',
  `color_scheme` varchar(20) DEFAULT 'default' COMMENT '메뉴 색상 테마',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `is_system_menu` tinyint(1) NOT NULL DEFAULT 0 COMMENT '시스템 메뉴 여부 (홈 등)',
  `url_slug` varchar(100) DEFAULT NULL COMMENT 'URL 슬러그 (SEO용)',
  `created_by` int(11) DEFAULT NULL COMMENT '생성자 ID (users 테이블과 연결)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_name` (`name`),
  UNIQUE KEY `unique_url_slug` (`url_slug`),
  KEY `idx_shop_menus_order` (`display_order`),
  KEY `idx_shop_menus_active` (`is_active`),
  KEY `idx_shop_menus_system` (`is_system_menu`),
  KEY `idx_shop_menus_created_by` (`created_by`),
  KEY `idx_shop_menus_active_order` (`is_active`,`display_order`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='쇼핑몰 네비게이션 메뉴 관리';


DROP TABLE IF EXISTS `shopping_cart`;
CREATE TABLE `shopping_cart` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `store_id` int(11) NOT NULL COMMENT '상품을 구매할 점포',
  `quantity` int(11) NOT NULL DEFAULT 1,
  `added_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cart_user_product_store` (`user_id`,`product_id`,`store_id`),
  KEY `idx_shopping_cart_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `store_transfer_items`;
CREATE TABLE `store_transfer_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transfer_id` int(11) NOT NULL COMMENT '이동 ID',
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `quantity` int(11) NOT NULL COMMENT '이동 수량',
  `unit_cost_price` decimal(10,2) NOT NULL COMMENT '단위 원가',
  `total_price` decimal(12,2) NOT NULL COMMENT '총 원가',
  `remarks` varchar(255) DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_transfer_id` (`transfer_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='점간이동 상세 항목';


DROP TABLE IF EXISTS `store_transfers`;
CREATE TABLE `store_transfers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `from_store_id` int(11) NOT NULL COMMENT '출발 점포 ID',
  `to_store_id` int(11) NOT NULL COMMENT '목적지 점포 ID',
  `user_id` int(11) NOT NULL COMMENT '이동 요청자 ID',
  `transfer_date` date NOT NULL COMMENT '이동 날짜',
  `total_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '총 이동 금액 (원가 기준)',
  `final_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '최종 금액',
  `status` enum('draft','confirmed','cancelled') NOT NULL DEFAULT 'draft' COMMENT '상태',
  `notes` text DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_from_store_id` (`from_store_id`),
  KEY `idx_to_store_id` (`to_store_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_transfer_date` (`transfer_date`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='점간이동 마스터';


DROP TABLE IF EXISTS `stores`;
CREATE TABLE `stores` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `suppliers`;
CREATE TABLE `suppliers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `contact_person` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `memo` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `full_name` varchar(100) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `role` enum('user','admin','super_admin') NOT NULL DEFAULT 'user',
  `store_id` int(11) unsigned DEFAULT NULL,
  `remember_token` varchar(255) DEFAULT NULL,
  `remember_token_expiry` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `google_id` varchar(255) DEFAULT NULL COMMENT '구글 계정 고유 ID',
  `auth_provider` enum('email','google') DEFAULT 'email' COMMENT '인증 제공자',
  `profile_image_url` text DEFAULT NULL COMMENT '프로필 이미지 URL',
  `default_delivery_address_id` int(11) DEFAULT NULL COMMENT '기본 배달 주소 ID',
  `preferred_language` enum('en','ko') DEFAULT 'en' COMMENT '선호 언어',
  `phone_verified` tinyint(1) DEFAULT 0 COMMENT '전화번호 인증 여부',
  `is_delivery_available` tinyint(1) DEFAULT 1 COMMENT '배달 서비스 이용 가능 여부',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `google_id` (`google_id`),
  KEY `fk_user_store` (`store_id`),
  KEY `idx_users_google_id` (`google_id`),
  KEY `fk_users_default_delivery_address` (`default_delivery_address_id`),
  CONSTRAINT `fk_user_store` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_users_default_delivery_address` FOREIGN KEY (`default_delivery_address_id`) REFERENCES `delivery_addresses` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `wholesale_customers`;
CREATE TABLE `wholesale_customers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT '거래처명',
  `phone` varchar(50) DEFAULT NULL COMMENT '전화번호',
  `address` text DEFAULT NULL COMMENT '주소',
  `memo` text DEFAULT NULL COMMENT '기타 메모',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `idx_phone` (`phone`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 거래처 정보';


DROP TABLE IF EXISTS `wholesale_products`;
CREATE TABLE `wholesale_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `wholesale_name_ko` varchar(255) DEFAULT NULL,
  `wholesale_name_en` varchar(255) DEFAULT NULL,
  `wholesale_skus` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`wholesale_skus`)),
  `wholesale_description` text DEFAULT NULL,
  `store_id` int(11) NOT NULL COMMENT '점포 ID',
  `wholesale_price` decimal(10,2) NOT NULL COMMENT '도매가',
  `cost_price` decimal(10,2) DEFAULT 0.00,
  `margin_rate` decimal(5,2) DEFAULT 15.00,
  `min_quantity` int(11) DEFAULT 1 COMMENT '최소 주문 수량',
  `sale_unit` enum('box','piece') NOT NULL DEFAULT 'box',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `cost_price_piece` decimal(10,2) DEFAULT 0.00 COMMENT '낱개 원가',
  `wholesale_price_piece` decimal(10,2) DEFAULT 0.00 COMMENT '낱개 판매가',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_product_store` (`product_id`,`store_id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 상품 가격 정보';


DROP TABLE IF EXISTS `wholesale_sale_items`;
CREATE TABLE `wholesale_sale_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_id` int(11) NOT NULL COMMENT '판매 ID',
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `quantity` int(11) NOT NULL COMMENT '수량',
  `unit_price` decimal(10,2) NOT NULL COMMENT '단가',
  `total_price` decimal(12,2) NOT NULL COMMENT '총가격',
  `remarks` varchar(200) DEFAULT NULL COMMENT '상품별 비고 (배송지시, 포장요청 등)',
  `notes` varchar(255) DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `sale_unit` enum('box','piece') NOT NULL DEFAULT 'box' COMMENT '판매단위 (box: 박스, piece: 낱개)',
  PRIMARY KEY (`id`),
  KEY `idx_sale_id` (`sale_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=188 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 판매 항목';


DROP TABLE IF EXISTS `wholesale_sales`;
CREATE TABLE `wholesale_sales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL COMMENT '거래처 ID',
  `store_id` int(11) NOT NULL COMMENT '점포 ID',
  `user_id` int(11) NOT NULL COMMENT '판매자 ID',
  `sale_date` date NOT NULL COMMENT '판매 날짜',
  `total_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '총 판매 금액',
  `tax_amount` decimal(12,2) DEFAULT 0.00 COMMENT '세금 금액',
  `discount_amount` decimal(12,2) DEFAULT 0.00 COMMENT '할인 금액',
  `final_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '최종 금액',
  `status` enum('draft','confirmed','cancelled') NOT NULL DEFAULT 'draft' COMMENT '상태',
  `notes` text DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_sale_date` (`sale_date`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 판매 내역';


DROP TABLE IF EXISTS `wishlists`;
CREATE TABLE `wishlists` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `added_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wishlist_user_product` (`user_id`,`product_id`),
  KEY `idx_wishlists_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
